1	package com.example.starter.hazmat.service;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.LocalDateTime;
7	import java.util.ArrayList;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.Optional;
12	
13	import org.springframework.dao.DuplicateKeyException;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.PlatformTransactionManager;
16	import org.springframework.transaction.support.TransactionTemplate;
17	
18	import com.example.starter.hazmat.api.ApiException;
19	import com.example.starter.hazmat.clock.MutableClock;
20	import com.example.starter.hazmat.domain.RouteApprovalStatus;
21	import com.example.starter.hazmat.domain.ShipmentStatus;
22	import com.example.starter.hazmat.domain.WaypointState;
23	import com.example.starter.hazmat.dto.ApplyRequest;
24	import com.example.starter.hazmat.dto.CheckinRequest;
25	import com.example.starter.hazmat.dto.RerouteRequest;
26	import com.example.starter.hazmat.po.ApprovalWaypoint;
27	import com.example.starter.hazmat.po.Checkin;
28	import com.example.starter.hazmat.po.GoodsCategory;
29	import com.example.starter.hazmat.po.IdempotentRecord;
30	import com.example.starter.hazmat.po.RouteApproval;
31	import com.example.starter.hazmat.po.RouteInfo;
32	import com.example.starter.hazmat.po.RouteWaypointDef;
33	import com.example.starter.hazmat.po.Shipment;
34	import com.example.starter.hazmat.po.ShipmentEvent;
35	import com.example.starter.hazmat.repo.HazmatRepository;
36	import com.fasterxml.jackson.core.JsonProcessingException;
37	import com.fasterxml.jackson.databind.ObjectMapper;
38	
39	/**
40	 * 危化品运输路线管制与押运打卡核心服务。
41	 *
42	 * <p>事务边界：写操作通过 {@link TransactionTemplate} 显式包裹；幂等占位独立于业务事务提交，
43	 * 业务失败（含逆序打卡拒绝）也记录首次结果用于同键重放；逆序告警使用独立事务保证回滚不丢告警。
44	 */
45	@Service
46	public class HazmatService {
47	
48	    /** 事件类型。 */
49	    public static final String EVT_ROUTE_REJECTED = "ROUTE_REJECTED";
50	    public static final String EVT_REROUTE_REJECTED = "REROUTE_REJECTED";
51	    public static final String EVT_REROUTE_SWITCH = "REROUTE_SWITCH";
52	    public static final String EVT_CHECKIN_REVERSED = "CHECKIN_REVERSED";
53	    public static final String EVT_DEVIATION_WARNING = "DEVIATION_WARNING";
54	    public static final String EVT_LOST_CONTACT = "LOST_CONTACT";
55	    public static final String EVT_LATE_CHECKIN_AFTER_CLOSE = "LATE_CHECKIN_AFTER_CLOSE";
56	
57	    /** 连续超时途经点数达到该值即升级失联（恰 2 个触发）。 */
58	    static final int LOST_CONTACT_CONSECUTIVE_TIMEOUTS = 2;
59	
60	    private final HazmatRepository repository;
61	    private final EventRecorder eventRecorder;
62	    private final MutableClock clock;
63	    private final TransactionTemplate tx;
64	    private final ObjectMapper objectMapper;
65	
66	    public HazmatService(HazmatRepository repository, EventRecorder eventRecorder,
67	                         MutableClock clock, PlatformTransactionManager transactionManager,
68	                         ObjectMapper objectMapper) {
69	        this.repository = repository;
70	        this.eventRecorder = eventRecorder;
71	        this.clock = clock;
72	        this.tx = new TransactionTemplate(transactionManager);
73	        this.objectMapper = objectMapper;
74	    }
75	
76	    private LocalDateTime now() {
77	        return clock.now();
78	    }
79	
80	    // ============================ 运输申请 ============================
81	
82	    public ServiceResult apply(ApplyRequest request) {
83	        String fingerprint = fingerprint("APPLY",
84	                request.requestId(), request.vehiclePlate(), request.goodsCategory(),
85	                request.routeCode(), request.plannedDeparture().toString());
86	        return withIdempotency(request.requestId(), fingerprint,
87	                () -> tx.execute(status -> doApply(request)));
88	    }
89	
90	    private ServiceResult doApply(ApplyRequest request) {
91	        LocalDateTime now = now();
92	        GoodsCategory category = repository.findCategory(request.goodsCategory())
93	                .orElseThrow(() -> ApiException.badRequest("CATEGORY_NOT_FOUND",
94	                        "危化品类别不存在: " + request.goodsCategory()));
95	        RouteInfo route = repository.findRoute(request.routeCode())
96	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND",
97	                        "路线不存在: " + request.routeCode()));
98	        var vehicle = repository.findVehicle(request.vehiclePlate())
99	                .orElseThrow(() -> ApiException.badRequest("VEHICLE_NOT_FOUND",
100	                        "车辆不存在: " + request.vehiclePlate()));
101	        if (vehicle.frozen()) {
102	            throw ApiException.conflict("VEHICLE_FROZEN",
103	                    "车辆 " + request.vehiclePlate() + " 已因失联冻结，禁止新申请");
104	        }
105	        if (repository.findActiveShipment(request.vehiclePlate()).isPresent()) {
106	            throw ApiException.conflict("VEHICLE_BUSY",
107	                    "车辆 " + request.vehiclePlate() + " 同时刻只允许一个执行中运单");
108	        }
109	        List<RouteWaypointDef> defs = repository.findWaypointDefs(request.routeCode());
110	        if (defs.isEmpty()) {
111	            throw ApiException.badRequest("ROUTE_WAYPOINTS_MISSING",
112	                    "路线 " + request.routeCode() + " 未定义途经点");
113	        }
114	
115	        String shipmentNo = "HZ" + request.plannedDeparture().toLocalDate().toString().replace("-", "")
116	                + "-" + Integer.toHexString(request.requestId().hashCode() & 0x7fffffff).toUpperCase();
117	        long shipmentId = repository.insertShipment(shipmentNo, request.vehiclePlate(),
118	                request.goodsCategory(), ShipmentStatus.APPLIED, null,
119	                request.plannedDeparture(), now);
120	        try {
121	            // 主键冲突即并发占用失败：回滚运单，返回 409。
122	            repository.occupyVehicle(request.vehiclePlate(), shipmentId);
123	        } catch (DuplicateKeyException e) {
124	            throw ApiException.conflict("VEHICLE_BUSY",
125	                    "车辆 " + request.vehiclePlate() + " 同时刻只允许一个执行中运单");
126	        }
127	        long approvalId = repository.insertApproval(shipmentId, request.routeCode(), 1,
128	                RouteApprovalStatus.PENDING, null, now);
129	        for (RouteWaypointDef def : defs) {
130	            repository.insertWaypoint(approvalId, shipmentId, def.seq(), def.name(),
131	                    request.plannedDeparture().plusMinutes(def.offsetMinutes()), WaypointState.PENDING);
132	        }
133	        repository.updateCurrentApproval(shipmentId, approvalId);
134	
135	        Map<String, Object> body = baseShipmentView(repository.findShipmentById(shipmentId).orElseThrow());
136	        body.put("message", "申请已受理，等待路线核准");
137	        return ServiceResult.ok(body);
138	    }
139	
140	    // ============================ 路线核准 ============================
141	
142	    public ServiceResult decideApproval(String shipmentNo, boolean approved) {
143	        return tx.execute(status -> doDecide(shipmentNo, approved));
144	    }
145	
146	    private ServiceResult doDecide(String shipmentNo, boolean approved) {
147	        Shipment shipment = loadShipment(shipmentNo);
148	        if (shipment.status() != ShipmentStatus.APPLIED) {
149	            throw ApiException.conflict("INVALID_STATUS",
150	                    "运单当前状态 " + shipment.status() + "，不可路线核准");
151	        }
152	        RouteApproval approval = currentApproval(shipment);
153	        if (approval.status() != RouteApprovalStatus.PENDING || approval.versionNo() != 1) {
154	            throw ApiException.conflict("APPROVAL_NOT_PENDING", "首版路线核准记录状态异常");
155	        }
156	        LocalDateTime now = now();
157	
158	        RouteRuleEvaluator.Result result = evaluate(approval.routeCode(),
159	                shipment.goodsCategory(), shipment.plannedDeparture());
160	        if (!approved || !result.allowed()) {
161	            // 驳回事务必须落库（终态 + 释放车辆占用），故提交后返回 422，而非抛异常回滚。
162	            String reason = approved ? result.message() : "人工驳回";
163	            repository.updateApprovalStatus(approval.id(), RouteApprovalStatus.REJECTED, now);
164	            repository.insertEvent(shipment.id(), EVT_ROUTE_REJECTED, reason, now);
165	            repository.updateStatus(shipment.id(), ShipmentStatus.ROUTE_REJECTED);
166	            repository.releaseVehicle(shipment.vehiclePlate());
167	            Map<String, Object> body = shipmentView(shipmentNo);
168	            body.put("errorCode", "ROUTE_REJECTED");
169	            body.put("message", reason);
170	            return ServiceResult.status(422, body);
171	        }
172	        repository.updateApprovalStatus(approval.id(), RouteApprovalStatus.APPROVED, now);
173	        repository.updateStatus(shipment.id(), ShipmentStatus.ROUTE_APPROVED);
174	        return ServiceResult.ok(shipmentView(shipmentNo));
175	    }
176	
177	    // ============================ 发运 ============================
178	
179	    public ServiceResult dispatch(String shipmentNo, String requestId) {
180	        String fingerprint = fingerprint("DISPATCH", requestId, shipmentNo);
181	        return withIdempotency(requestId, fingerprint,
182	                () -> tx.execute(status -> doDispatch(shipmentNo)));
183	    }
184	
185	    private ServiceResult doDispatch(String shipmentNo) {
186	        Shipment shipment = loadShipment(shipmentNo);
187	        if (shipment.status() == ShipmentStatus.DISPATCHED || shipment.status() == ShipmentStatus.IN_TRANSIT) {
188	            throw ApiException.conflict("ALREADY_DISPATCHED", "运单已发运");
189	        }
190	        if (shipment.status() != ShipmentStatus.ROUTE_APPROVED) {
191	            throw ApiException.conflict("INVALID_STATUS",
192	                    "运单当前状态 " + shipment.status() + "，不可发运");
193	        }
194	        repository.updateStatus(shipment.id(), ShipmentStatus.DISPATCHED);
195	        return ServiceResult.ok(shipmentView(shipmentNo));
196	    }
197	
198	    // ============================ 押运打卡 ============================
199	
200	    public ServiceResult checkin(String shipmentNo, CheckinRequest request) {
201	        String fingerprint = fingerprint("CHECKIN", request.requestId(), shipmentNo,
202	                String.valueOf(request.waypointSeq()), request.checkTime().toString());
203	        // 逆序拒绝走异常路径：告警独立事务落库，业务事务回滚，首次失败响应同样幂等保存。
204	        return withIdempotency(request.requestId(), fingerprint,
205	                () -> tx.execute(status -> doCheckin(shipmentNo, request)));
206	    }
207	
208	    private ServiceResult doCheckin(String shipmentNo, CheckinRequest request) {
209	        Shipment shipment = loadShipment(shipmentNo);
210	        LocalDateTime now = now();
211	
212	        if (shipment.status() == ShipmentStatus.COMPLETED) {
213	            // 结案为终态：迟到打卡不改任何业务状态，只记录迟到事件。
214	            eventRecorder.recordNewTransaction(shipment.id(), EVT_LATE_CHECKIN_AFTER_CLOSE,
215	                    "结案后收到途经点 " + request.waypointSeq() + " 打卡，时刻 " + request.checkTime(), now);
216	            Map<String, Object> body = shipmentView(shipmentNo);
217	            body.put("lateAfterClosed", true);
218	            return ServiceResult.ok(body);
219	        }
220	        if (shipment.status().isTerminal()) {
221	            throw ApiException.conflict("SHIPMENT_TERMINAL",
222	                    "运单终态 " + shipment.status() + "，不可打卡");
223	        }
224	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
225	            throw ApiException.conflict("NOT_DISPATCHED",
226	                    "运单当前状态 " + shipment.status() + "，不可打卡");
227	        }
228	
229	        long approvalId = shipment.currentApprovalId();
230	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approvalId);
231	        ApprovalWaypoint target = waypoints.stream()
232	                .filter(w -> w.seq() == request.waypointSeq()).findFirst()
233	                .orElseThrow(() -> ApiException.badRequest("WAYPOINT_NOT_FOUND",
234	                        "当前路线无途经点序号 " + request.waypointSeq()));
235	
236	        Optional<Checkin> duplicate = repository.findCheckin(shipment.id(), approvalId, target.seq());
237	        if (duplicate.isPresent()) {
238	            throw ApiException.conflict("WAYPOINT_ALREADY_CHECKED",
239	                    "途经点 " + target.seq() + " 已打卡（运单+途经点序号去重），首次打卡时刻 "
240	                            + duplicate.get().checkTime());
241	        }
242	
243	        // 时序校验：与最近的前序、后序已打卡途经点比较；乱序回传允许（按时刻归位），时刻逆序拒绝并告警。
244	        Checkin prev = nearestChecked(waypoints, target.seq(), true);
245	        Checkin next = nearestChecked(waypoints, target.seq(), false);
246	        if (prev != null && !request.checkTime().isAfter(prev.checkTime())) {
247	            rejectReverse(shipment, target.seq(), request.checkTime(),
248	                    "晚于前序途经点 " + prev.seq() + " 的打卡时刻 " + prev.checkTime(), now);
249	        }
250	        if (next != null && !request.checkTime().isBefore(next.checkTime())) {
251	            rejectReverse(shipment, target.seq(), request.checkTime(),
252	                    "早于后序途经点 " + next.seq() + " 的打卡时刻 " + next.checkTime(), now);
253	        }
254	
255	        boolean late = !request.checkTime().isBefore(target.deadline());
256	        WaypointState targetState = late ? WaypointState.CHECKED_LATE : WaypointState.CHECKED;
257	        int rows;
258	        if (late) {
259	            // 既可能从未扫描（PENDING），也可能已被标记偏离（TIMED_OUT）。
260	            rows = repository.compareAndSetWaypointState(approvalId, target.seq(),
261	                    WaypointState.PENDING, targetState, request.checkTime())
262	                    + repository.compareAndSetWaypointState(approvalId, target.seq(),
263	                    WaypointState.TIMED_OUT, targetState, request.checkTime());
264	        } else {
265	            rows = repository.compareAndSetWaypointState(approvalId, target.seq(),
266	                    WaypointState.PENDING, targetState, request.checkTime());
267	        }
268	        if (rows == 0) {
269	            // 并发：监控扫描或另一打卡刚刚改变状态。
270	            Optional<Checkin> raced = repository.findCheckin(shipment.id(), approvalId, target.seq());
271	            if (raced.isPresent()) {
272	                throw ApiException.conflict("WAYPOINT_ALREADY_CHECKED",
273	                        "途经点 " + target.seq() + " 已打卡，首次打卡时刻 " + raced.get().checkTime());
274	            }
275	            throw ApiException.conflict("WAYPOINT_STATE_CHANGED",
276	                    "途经点 " + target.seq() + " 状态刚被更新，请重试");
277	        }
278	        repository.insertCheckin(shipment.id(), approvalId, target.seq(),
279	                request.checkTime(), request.requestId(), now);
280	        if (shipment.status() == ShipmentStatus.DISPATCHED) {
281	            repository.updateStatus(shipment.id(), ShipmentStatus.IN_TRANSIT);
282	        }
283	        return ServiceResult.ok(shipmentView(shipmentNo));
284	    }
285	
286	    private void rejectReverse(Shipment shipment, int seq, LocalDateTime checkTime, String detail, LocalDateTime now) {
287	        String message = "途经点 " + seq + " 打卡时刻 " + checkTime + " 未" + detail + "，逆序拒绝";
288	        eventRecorder.recordNewTransaction(shipment.id(), EVT_CHECKIN_REVERSED, message, now);
289	        throw ApiException.badRequest("CHECKIN_REVERSED", message);
290	    }
