390	    // ============================ 到达核销 ============================
391	
392	    public ServiceResult complete(String shipmentNo, String requestId) {
393	        String fingerprint = fingerprint("COMPLETE", requestId, shipmentNo);
394	        return withIdempotency(requestId, fingerprint,
395	                () -> tx.execute(status -> doComplete(shipmentNo)));
396	    }
397	
398	    private ServiceResult doComplete(String shipmentNo) {
399	        Shipment shipment = loadShipment(shipmentNo);
400	        if (shipment.status() == ShipmentStatus.COMPLETED) {
401	            // 结案终态：重复核销（无论是否同 requestId）返回幂等成功。
402	            return ServiceResult.ok(shipmentView(shipmentNo));
403	        }
404	        if (shipment.status() == ShipmentStatus.LOST_CONTACT) {
405	            throw ApiException.conflict("ALREADY_LOST_CONTACT", "运单已失联冻结，不可核销");
406	        }
407	        // 条件更新：与失联升级竞争，败者拿不到终态。
408	        int rows = repository.compareAndSetTerminal(shipment.id(), ShipmentStatus.COMPLETED);
409	        if (rows == 0) {
410	            Shipment current = repository.findShipmentById(shipment.id()).orElseThrow();
411	            if (current.status() == ShipmentStatus.COMPLETED) {
412	                return ServiceResult.ok(shipmentView(shipmentNo));
413	            }
414	            throw ApiException.conflict("ALREADY_LOST_CONTACT", "运单已失联冻结，不可核销");
415	        }
416	        repository.releaseVehicle(shipment.vehiclePlate());
417	        return ServiceResult.ok(shipmentView(shipmentNo));
418	    }
419	
420	    // ============================ 超时/失联监控（可复算） ============================
421	
422	    public ServiceResult scanTimeouts(LocalDateTime at) {
423	        LocalDateTime now = at != null ? at : now();
424	        List<Map<String, Object>> affected = new ArrayList<>();
425	        List<Shipment> actives;
426	        try {
427	            actives = tx.execute(status -> repository.findActiveShipments());
428	        } catch (Exception e) {
429	            throw ApiException.badRequest("SCAN_FAILED", e.getMessage());
430	        }
431	        for (Shipment shipment : actives) {
432	            if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
433	                continue;
434	            }
435	            try {
436	                Map<String, Object> changed = tx.execute(status -> scanOne(shipment.id(), now));
437	                if (changed != null && Boolean.TRUE.equals(changed.get("changed"))) {
438	                    affected.add(changed);
439	                }
440	            } catch (ApiException e) {
441	                throw e;
442	            } catch (Exception ignored) {
443	                // 单个运单扫描失败不影响其他运单（终态竞争败者等）。
444	            }
445	        }
446	        return ServiceResult.ok(Map.of("scanAt", now.toString(), "affected", affected));
447	    }
448	
449	    /** 扫描单个运单：标记超时点；连续 2 点超时则升级失联并冻结（唯一终态 CAS）。 */
450	    private Map<String, Object> scanOne(long shipmentId, LocalDateTime now) {
451	        Shipment shipment = repository.findShipmentById(shipmentId).orElseThrow();
452	        if (shipment.status().isTerminal()) {
453	            return Map.of();
454	        }
455	        long approvalId = shipment.currentApprovalId();
456	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approvalId);
457	        List<Integer> timedOut = new ArrayList<>();
458	        for (ApprovalWaypoint w : waypoints) {
459	            if (w.state() == WaypointState.PENDING && !now.isBefore(w.deadline())) {
460	                int rows = repository.compareAndSetWaypointState(approvalId, w.seq(),
461	                        WaypointState.PENDING, WaypointState.TIMED_OUT, null);
462	                if (rows == 1) {
463	                    timedOut.add(w.seq());
464	                    repository.insertEvent(shipmentId, EVT_DEVIATION_WARNING,
465	                            "途经点 " + w.seq() + "(" + w.name() + ") 计划通过时刻 " + w.plannedTime()
466	                                    + "，超时阈值 " + w.deadline() + "，扫描时刻 " + now + " 仍未打卡", now);
467	                }
468	            }
469	        }
470	        boolean lost = hasConsecutiveTimeouts(repository.findWaypoints(approvalId));
471	        boolean upgraded = false;
472	        if (lost) {
473	            int rows = repository.compareAndSetTerminal(shipmentId, ShipmentStatus.LOST_CONTACT);
474	            if (rows == 1) {
475	                upgraded = true;
476	                repository.freezeVehicle(shipment.vehiclePlate(), shipmentId, now);
477	                repository.releaseVehicle(shipment.vehiclePlate());
478	                repository.insertEvent(shipmentId, EVT_LOST_CONTACT,
479	                        "连续 2 个途经点超时未打卡，升级失联并冻结车辆 " + shipment.vehiclePlate(), now);
480	            }
481	        }
482	        if (timedOut.isEmpty() && !upgraded) {
483	            return Map.of();
484	        }
485	        Map<String, Object> changed = new LinkedHashMap<>();
486	        changed.put("changed", true);
487	        changed.put("shipmentNo", shipment.shipmentNo());
488	        changed.put("newlyTimedOut", timedOut);
489	        changed.put("lostContact", upgraded);
490	        return changed;
491	    }
492	
493	    /** 连续超时判定：按序号相邻的两个途经点均处于 TIMED_OUT（恰 2 个即触发）。 */
494	    static boolean hasConsecutiveTimeouts(List<ApprovalWaypoint> waypoints) {
495	        List<ApprovalWaypoint> sorted = waypoints.stream()
496	                .sorted(java.util.Comparator.comparingInt(ApprovalWaypoint::seq)).toList();
497	        int consecutive = 0;
498	        for (ApprovalWaypoint w : sorted) {
499	            if (w.state() == WaypointState.TIMED_OUT) {
500	                consecutive++;
501	                if (consecutive >= LOST_CONTACT_CONSECUTIVE_TIMEOUTS) {
502	                    return true;
503	                }
504	            } else {
505	                consecutive = 0;
506	            }
507	        }
508	        return false;
509	    }
