536	    private Map<String, Object> baseShipmentView(Shipment shipment) {
537	        Map<String, Object> body = new LinkedHashMap<>();
538	        body.put("shipmentNo", shipment.shipmentNo());
539	        body.put("vehiclePlate", shipment.vehiclePlate());
540	        body.put("goodsCategory", shipment.goodsCategory());
541	        body.put("status", shipment.status().name());
542	        body.put("terminal", shipment.status().isTerminal());
543	        body.put("plannedDeparture", shipment.plannedDeparture().toString());
544	        return body;
