547	    private Map<String, Object> shipmentView(String shipmentNo) {
548	        Shipment shipment = loadShipment(shipmentNo);
549	        Map<String, Object> body = baseShipmentView(shipment);
550	        repository.findVehicle(shipment.vehiclePlate()).ifPresent(v -> body.put("vehicleFrozen", v.frozen()));
551	
552	        List<Map<String, Object>> approvalViews = new ArrayList<>();
553	        for (RouteApproval approval : repository.findApprovals(shipment.id())) {
554	            Map<String, Object> av = new LinkedHashMap<>();
555	            av.put("approvalId", approval.id());
556	            av.put("versionNo", approval.versionNo());
557	            av.put("routeCode", approval.routeCode());
558	            av.put("status", approval.status().name());
559	            av.put("rejectReason", approval.rejectReason());
560	            av.put("current", approval.id() == shipment.currentApprovalId());
561	
562	            List<Checkin> checkins = repository.findCheckinsByApproval(approval.id());
563	            List<Map<String, Object>> wpViews = new ArrayList<>();
564	            for (ApprovalWaypoint w : repository.findWaypoints(approval.id())) {
565	                Map<String, Object> wv = new LinkedHashMap<>();
566	                wv.put("seq", w.seq());
567	                wv.put("name", w.name());
568	                wv.put("plannedTime", w.plannedTime().toString());
569	                wv.put("deadline", w.deadline().toString());
570	                wv.put("state", w.state().name());
571	                wv.put("checkedTime", w.checkedTime() == null ? null : w.checkedTime().toString());
572	                checkins.stream().filter(c -> c.seq() == w.seq()).findFirst()
573	                        .ifPresent(c -> wv.put("requestId", c.requestId()));
574	                wpViews.add(wv);
575	            }
576	            av.put("waypoints", wpViews);
577	            approvalViews.add(av);
578	        }
579	        body.put("approvals", approvalViews);
580	
581	        List<Map<String, Object>> eventViews = new ArrayList<>();
582	        for (ShipmentEvent e : repository.findEvents(shipment.id())) {
583	            Map<String, Object> ev = new LinkedHashMap<>();
584	            ev.put("eventType", e.eventType());
585	            ev.put("detail", e.detail());
586	            ev.put("eventTime", e.eventTime().toString());
587	            eventViews.add(ev);
588	        }
589	        body.put("events", eventViews);
590	        return body;
591	    }
