102	    /** 冻结车辆（失联升级时），幂等条件：仅未冻结车辆生效，返回受影响行数。 */
103	    public int freezeVehicle(String plate, long shipmentId, LocalDateTime now) {
104	        return jdbc.update("UPDATE vehicle SET frozen = 1, frozen_shipment_id = ?, frozen_at = ? WHERE plate = ? AND frozen = 0",
105	                shipmentId, Timestamp.valueOf(now), plate);
