107	
108	    // ---------- 在途占用 ----------
109	
110	    /** 占用车辆：并发下主键冲突抛 {@link DuplicateKeyException}。 */
111	    public void occupyVehicle(String plate, long shipmentId) {
112	        jdbc.update("INSERT INTO vehicle_active_shipment (vehicle_plate, shipment_id) VALUES (?, ?)",
113	                plate, shipmentId);
114	    }
115	
116	    public Optional<Long> findActiveShipment(String plate) {
117	        return jdbc.query("SELECT shipment_id FROM vehicle_active_shipment WHERE vehicle_plate = ?",
118	                (rs, n) -> rs.getLong("shipment_id"), plate).stream().findFirst();
119	    }
