121	    /** 释放占用（运单进入终态时）。 */
122	    public void releaseVehicle(String plate) {
123	        jdbc.update("DELETE FROM vehicle_active_shipment WHERE vehicle_plate = ?", plate);
124	    }
125	
126	    // ---------- 幂等 ----------
127	
128	    private static final RowMapper<IdempotentRecord> IDEMPOTENT_MAPPER = (rs, n) ->
129	            new IdempotentRecord(rs.getString("request_id"), rs.getString("fingerprint"),
130	                    rs.getString("status"), (Integer) rs.getObject("http_status"),
131	                    rs.getString("response_body"),
132	                    rs.getTimestamp("created_at").toLocalDateTime());
133	
134	    public Optional<IdempotentRecord> findIdempotent(String requestId) {
135	        return jdbc.query("SELECT request_id, fingerprint, status, http_status, response_body, created_at FROM idempotent_record WHERE request_id = ?",
136	                IDEMPOTENT_MAPPER, requestId).stream().findFirst();
137	    }
138	
139	    /** 插入处理中占位；并发同键返回 false。 */
140	    public boolean insertProcessingIdempotent(String requestId, String fingerprint, LocalDateTime now) {
141	        try {
142	            int rows = jdbc.update("INSERT INTO idempotent_record (request_id, fingerprint, status, http_status, response_body, created_at) VALUES (?, ?, 'PROCESSING', NULL, NULL, ?)",
143	                    requestId, fingerprint, Timestamp.valueOf(now));
144	            return rows == 1;
145	        } catch (DuplicateKeyException e) {
146	            return false;
147	        }
