1	package com.example.starter.hazmat;
2	
3	import static org.assertj.core.api.Assertions.assertThat;
4	import static org.assertj.core.api.Assertions.assertThatThrownBy;
5	
6	import java.time.LocalDateTime;
7	
8	import org.junit.jupiter.api.Test;
9	
10	import com.example.starter.hazmat.api.ApiException;
11	
12	/**
13	 * 超时监控与失联升级：恰 60 分钟边界、偏离预警、连续 2 点超时升级失联并冻结车辆。
14	 *
15	 * <p>R-G1 计划（发运 08:00）：p0 08:30 阈值 09:30、p1 09:00 阈值 10:00、p2 09:30 阈值 10:30。
16	 */
17	class MonitorAndLostContactTest extends HazmatIntegrationTestBase {
18	
19	    private static final LocalDateTime DEPARTURE = LocalDateTime.parse("2026-10-02T08:00:00");
20	
21	    private String dispatched(String plate) {
22	        String no = shipmentNo(apply("m-apply-" + plate, plate, "TOXIC", "R-G1", DEPARTURE));
23	        approve(no);
24	        dispatch(no, "m-dispatch-" + plate);
25	        return no;
26	    }
27	
28	    @Test
29	    void deadlineBoundarySinglePointIsWarningOnly() {
30	        String no = dispatched("沪A-1001");
31	        // 09:29:59：p0 未到阈值（恰满 60 分钟才算），无标记。
32	        scan(LocalDateTime.parse("2026-10-02T09:29:59"));
33	        assertThat(waypoint(no, 0).get("state")).isEqualTo("PENDING");
34	        assertThat(view(no).get("status")).isEqualTo("DISPATCHED");
35	
36	        // 09:30:00 恰满 60 分钟：p0 标记偏离预警，仅 1 点不离联。
37	        scan(LocalDateTime.parse("2026-10-02T09:30:00"));
38	        assertThat(waypoint(no, 0).get("state")).isEqualTo("TIMED_OUT");
39	        assertThat(view(no).get("status")).isEqualTo("DISPATCHED");
40	        assertThat(events(view(no)).stream()
41	                .anyMatch(e -> "DEVIATION_WARNING".equals(e.get("eventType")))).isTrue();
42	
43	        // 复算：再次扫描幂等，不重复产生超时点。
44	        var again = scan(LocalDateTime.parse("2026-10-02T09:45:00"));
45	        @SuppressWarnings("unchecked")
46	        java.util.List<java.util.Map<String, Object>> affected =
47	                (java.util.List<java.util.Map<String, Object>>) again.body().get("affected");
48	        assertThat(affected).isEmpty();
49	        assertThat(events(view(no)).stream()
50	                .filter(e -> "DEVIATION_WARNING".equals(e.get("eventType"))).count()).isEqualTo(1);
51	    }
52	
53	    @Test
54	    void twoConsecutiveTimeoutsEscalateToLostContactAndFreeze() {
55	        String no = dispatched("沪A-1002");
56	        // 10:00：p0、p1 均超时（恰 2 个连续点）→ 失联终态 + 车辆冻结 + 占用释放。
57	        scan(LocalDateTime.parse("2026-10-02T10:00:00"));
58	        var view = view(no);
59	        assertThat(view.get("status")).isEqualTo("LOST_CONTACT");
60	        assertThat(view.get("terminal")).isEqualTo(true);
61	        assertThat(view.get("vehicleFrozen")).isEqualTo(true);
62	        assertThat(repository.findVehicle("沪A-1002").orElseThrow().frozen()).isTrue();
63	        assertThat(repository.findActiveShipment("沪A-1002")).isEmpty();
64	        assertThat(events(view).stream().anyMatch(e -> "LOST_CONTACT".equals(e.get("eventType")))).isTrue();
65	
66	        // 冻结后新车申请被拒。
67	        assertThatThrownBy(() -> apply("m-after-freeze", "沪A-1002", "TOXIC", "R-G1", DEPARTURE))
68	                .isInstanceOf(ApiException.class)
69	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("VEHICLE_FROZEN"));
70	        // 失联运单不可再打卡。
71	        assertThatThrownBy(() -> checkin(no, "m-late", 2, DEPARTURE.plusMinutes(100)))
72	                .isInstanceOf(ApiException.class)
73	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("SHIPMENT_TERMINAL"));
74	    }
75	
76	    @Test
77	    void nonConsecutiveTimeoutsDoNotEscalate() {
78	        String no = dispatched("沪B-2001");
79	        // 先打中间点 p1（时刻 09:05，无相邻已打卡点，合法）。
80	        checkin(no, "m-p1", 1, DEPARTURE.plusMinutes(65));
81	        // 10:30：p0 与 p2 超时，但被已打卡的 p1 隔开，不连续 → 不离联。
82	        scan(LocalDateTime.parse("2026-10-02T10:30:00"));
83	        var view = view(no);
84	        assertThat(view.get("status")).isEqualTo("IN_TRANSIT");
85	        assertThat(waypoint(no, 0).get("state")).isEqualTo("TIMED_OUT");
86	        assertThat(waypoint(no, 2).get("state")).isEqualTo("TIMED_OUT");
