COMMENT ON COLUMN relay_segment.incoming_time IS '接班打卡时刻（Asia/Shanghai）；未打卡为NULL';
COMMENT ON COLUMN relay_segment.completed_at IS '换班完成登记时刻；未完成为NULL';

